const publicKeyPem = pm.collectionVariables.get("clientPublicKeyPem");

if (
  typeof publicKeyPem !== "string" ||
  !publicKeyPem.includes("-----BEGIN PUBLIC KEY-----") ||
  !publicKeyPem.includes("-----END PUBLIC KEY-----")
) {
  throw new Error("The clientPublicKeyPem variable is missing or invalid.");
}

const requestBody = JSON.stringify({
  publicKeyPem: publicKeyPem.trim()
});

pm.variables.set("clientEnrollmentChallengeBody", requestBody);

console.log("Public key length:", publicKeyPem.length);
console.log("Generated JSON body length:", requestBody.length);
console.log(
  "Public key field exists:",
  typeof JSON.parse(requestBody).publicKeyPem === "string"
);

